import static io.restassured.RestAssured.*;

public class UserContract {
    public boolean validate(String baseUrl) {
        var res = given().when().get(baseUrl + "/user").then().statusCode(200).extract();
        Object id = res.path("id");
        String email = res.path("email");
        String status = res.path("status");
        if (id == null) throw new AssertionError("id required");
        if (email == null || email.isBlank()) throw new AssertionError("email required");
        if (!"ACTIVE".equals(status)) throw new AssertionError("status ACTIVE required");
        return true;
    }
}

